impl Sem {
    fn new(n: u32) -> Self {
        Self {
            n: std::sync::Mutex::new(SemState {
                permits: n,
                owner: None,
                count: 0,
            }),
            cv: std::sync::Condvar::new(),
        }
    }

    fn acq(&self) {
        let me = std::thread::current().id();
        let mut c = self.n.lock().unwrap();
        if c.owner == Some(me) {
            c.count += 1;
            return;
        }
        while c.permits == 0 {
            c = self.cv.wait(c).unwrap();
        }
        c.permits -= 1;
        c.owner = Some(me);
        c.count = 1;
